SourceCode.Declaration:
/// <summary>
/// The <c>METDallasPicklistRegSalesConfirmContract</c> class is a data contract used for the MET Dallas picklist registration sales confirmation process.
/// </summary>
[DataContract] 
class METDallasPicklistRegSalesConfirmContract
{
    int tasksNumber;
    container wmsOrderTransRouteSet;
    container salesOrderCon;

}

Method.Source:
/// <summary>
/// This method takes task numbers.
/// </summary>
/// <param name = "_tasksNumber">TaskNumber</param>
/// <returns>TaskNumber</returns>
[DataMember,
    SysOperationLabelAttribute('No. of parallel tasks')
    ]

public int parmParallelTasksNumber(int _tasksNumber = tasksNumber)
{
    tasksNumber = _tasksNumber;
    return tasksNumber;
}

/// <summary>
/// Gets or sets the WMS order transaction route set.
/// </summary>
/// <param name = "wmsOrderTransRoute"> WMS order transaction route set.</param>
/// <returns> WMS order transaction route set.</returns>
[DataMember,
    SysOperationLabelAttribute('Picklist route set')
    ]
public container parmWMSOrderTransRouteSet(container _wmsOrderTransRouteSet = wmsOrderTransRouteSet)
{
    wmsOrderTransRouteSet = _wmsOrderTransRouteSet;
    return wmsOrderTransRouteSet;
}

/// <summary>
/// Gets or sets Sales order container.
/// </summary>
/// <param name = "wmsOrderTransRoute"> Sales order container.</param>
/// <returns> Sales order container.</returns>
[DataMember,
    SysOperationLabelAttribute('Sales orders')
    ]
public container parmSalesOrderCon(container _salesOrderCon = salesOrderCon)
{
    salesOrderCon = _salesOrderCon;
    return salesOrderCon;
}
